import{z as A,x as B,o as r,c as p,q as l,j as o,D as E,d as t,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"巨帧与 MTU","description":"","frontmatter":{"title":"巨帧与 MTU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jumbo-mtu.md","filePath":"cs/jumbo-mtu.md","lastUpdated":1791063341000}'),d={name:"cs/jumbo-mtu.md"};function m(T,a,u,P,C,D){const s=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="巨帧与-mtu" tabindex="-1">巨帧与 MTU <a class="header-anchor" href="#巨帧与-mtu" aria-label="Permalink to &quot;巨帧与 MTU&quot;">​</a></h1><div class="epigraph"><p>标准以太网载荷 1500 字节是历史互操作点；巨帧摊薄头开销，但路径上任一跳更小就会分片或丢弃。</p><footer>—— 据 IEEE 802.3 最大帧；RFC 1191 / 8201 路径 MTU；Kurose and Ross MTU 节整理</footer></div><p><a href="/cs/pause-pfc">上一课</a>管队列反压，不管帧有多长。主干<a href="/cs/ip-fragment">IP 分片</a> 已说明 MTU。缺口是<strong>链路上把帧做大</strong>：jumbo（常见 9000 字节载荷）降低 PPS 与头税，要求 VLAN、LACP、整条二层路径一致。本课不把 LACP 状态机写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每帧都有 MAC/IP/TCP 头。1500 在十吉比特上 PPS 仍高，CPU 与交换芯片查表次数多。加大 MTU 减帧数。代价：缓冲按最大帧预留；混合 1500/9000 的路径上，ICMP 需要分片或 PMTUD 后课才细讲——本课只钉二层必须先能装下。FCS 仍覆盖整帧，出错重传一整颗巨帧，无线或高误码介质上不划算。</p><p><span class="marginnote">术语翻译：MTU（最大传输单元）就是一条链路单次能装下的最大载荷，好比信封的最大规格——信写得再长，也只能按信封尺寸裁开分寄。巨帧就是把信封从 1500 字节加宽到约 9000 字节。</span></p><p>「Baby giant / 1518 vs 1522」是 VLAN tag 的历史缺口，已在主干 VLAN 课点过，这里不重推导。</p><p><span class="marginnote">9000 不是 IEEE 强制；厂商扩展。数据中心常见，广域互联网核心不假设巨帧。</span></p><h3 id="加大-mtu-不提高" tabindex="-1">加大 MTU 不提高 \\(C\\) <a class="header-anchor" href="#加大-mtu-不提高" aria-label="Permalink to &quot;加大 MTU 不提高 $C$&quot;">​</a></h3><p>只摊协议头与 PPS。路径最小 MTU 是公约数；混用 1500/9000 会丢或分片。FCS 失败时巨帧重传更痛。</p><p><span class="marginnote">数字实例：每帧协议头按 54 字节（MAC+IP+TCP）计，传 90,000 字节数据——MTU 1500 要 60 帧，头税 \\(60 \\times 54 = 3240\\) 字节；MTU 9000 只要 10 帧，头税 540 字节，交换芯片查表和主机中断也降到六分之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置：口 MTU、SVI、路由口、隧道外层各算一次。画：端主机 9000，中间交换机 1500 → 巨帧被丢，不是被 PAUSE。对照：提高 MTU 不提高 \\(C\\)，只摊协议头。</p>',13)),(r(),o(n,null,{default:E(()=>[i(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%20MTU%22%5D%20--%3E%20SW%5B%22%E6%B2%BF%E8%B7%AF%E4%BA%8C%E5%B1%82%20MTU%22%5D%0A%20%20SW%20--%3E%20OK%5B%22%E6%95%B4%E8%B7%AF%E4%B8%80%E8%87%B4%E5%88%99%E9%80%9A%E8%BF%87%22%5D%0A%20%20SW%20--%3E%20DROP%5B%22%E4%B8%80%E8%B7%B3%E6%9B%B4%E5%B0%8F%E5%88%99%E4%B8%A2%E6%88%96%E5%88%86%E7%89%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"TSO 后课会在主机侧切段；巨帧是链路允许更大的切。两者正交。PFC 缓冲阈值按最大帧计算，否则巨帧一来就过阈。容量仍是符号率的事：巨帧不增加 \\(C\\)。",-1)),a[5]||(a[5]=e("p",null,[t("与"),e("a",{href:"/cs/layering-e2e"},"端到端"),t("：更大的帧让链路 FEC/CRC 失败代价变大，所以高误码链路保持小帧。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「MTU 调大网速就变快了」。实际上链路容量 \\(C\\) 由符号率决定，巨帧只是少交「每帧固定过路费」——每秒能通过的总比特数一个都没多，只是管理开销变小。")],-1)),(r(),o(n,null,{default:E(()=>[i(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%A6%81%E5%8F%91%2090000%20%E5%AD%97%E8%8A%82%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20A%5B%22MTU%201500%EF%BC%9A%E5%88%87%E6%88%90%2060%20%E5%B8%A7%22%5D%0A%20%20D%20--%3E%20B%5B%22MTU%209000%EF%BC%9A%E5%88%87%E6%88%90%2010%20%E5%B8%A7%22%5D%0A%20%20A%20--%3E%20HA%5B%22%E5%A4%B4%E7%A8%8E%2060%20x%2054%20%3D%203240%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20B%20--%3E%20HB%5B%22%E5%A4%B4%E7%A8%8E%2010%20x%2054%20%3D%20540%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20HA%20--%3E%20P1%5B%22PPS%20%E9%AB%98%EF%BC%9A%E6%9F%A5%E8%A1%A8%E4%B8%8E%E4%B8%AD%E6%96%AD%20x60%22%5D%0A%20%20HB%20--%3E%20P2%5B%22PPS%20%E4%BD%8E%EF%BC%9A%E6%9F%A5%E8%A1%A8%E4%B8%8E%E4%B8%AD%E6%96%AD%20x10%22%5D%0A%20%20P1%20--%3E%20C%5B%22%E5%AE%B9%E9%87%8F%20C%20%E7%9B%B8%E5%90%8C%22%5D%0A%20%20P2%20--%3E%20C%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 PMTUD 黑洞写完（网络层进阶）。LACP 是下一课。后课默认：jumbo 是路径最小 MTU 的公约数问题，不是单口开关。</p><p>不要把 64 字节最小帧与巨帧对调：最小帧管冲突槽历史与填充，仍在。</p><p>下一课<a href="/cs/lacp">LACP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1500 是互操作默认；jumbo 摊头税、要路径一致。</li><li>加大 MTU 不提高香农容量。</li><li>分片/丢弃发生在最小 MTU 跳。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3；RFC 1191；Kurose and Ross。</li></ul>',6))])}const f=A(d,[["render",m]]);export{M as __pageData,f as default};
